            target_os = "android",
            target_os = "dragonfly",
            target_os = "freebsd",
            target_os = "fuchsia",
            target_os = "illumos",
            target_os = "linux",
            target_os = "netbsd",
            target_os = "openbsd"
        )))]
        let socket_ty = socket2::Type::STREAM;

        let socket = socket2::Socket::new(socket2::Domain::UNIX, socket_ty, None)?;

        #[cfg(not(any(
            target_os = "android",
            target_os = "dragonfly",
            target_os = "freebsd",
            target_os = "fuchsia",
            target_os = "illumos",
            target_os = "linux",
            target_os = "netbsd",
            target_os = "openbsd"
        )))]
        socket.set_nonblocking(true)?;

        let mut sockaddr = unsafe { std::mem::zeroed::<libc::sockaddr_un>() };
        sockaddr.sun_family = libc::AF_UNIX as libc::sa_family_t;
        let sockaddr_base = &sockaddr as *const libc::sockaddr_un as usize;
        let sun_path_ptr = std::ptr::addr_of!(sockaddr.sun_path) as usize;
        let path_offset = sun_path_ptr - sockaddr_base;
        let mut addrlen = path_offset;
        let mut copied = 0usize;

        match addr.as_pathname() {
            Some(pathname) => {
                let bytes = pathname.as_os_str().as_bytes();
                if bytes.is_empty() {
